CREATE FUNCTION pg_temp.check_it(ok boolean,message text) RETURNS void LANGUAGE plpgsql AS $$BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',message;END IF;END$$;
-- Exercise the real game engines with a synthetic server identity helper, not browser-supplied school IDs.
CREATE OR REPLACE FUNCTION public.require_supper_monitoring_session(p_token text) RETURNS public.supper_monitoring_sessions LANGUAGE plpgsql AS $$BEGIN
 IF p_token NOT IN('show-school-1','show-school-2','show-school-3','show-school-4') THEN RAISE EXCEPTION 'Invalid synthetic session';END IF;
 RETURN jsonb_populate_record(NULL::public.supper_monitoring_sessions,jsonb_build_object('location_id',900000+right(p_token,1)::int,'employee_id',900001,'actor_role','manager','expires_at',now()+interval '1 day'));
END$$;
DO $$
#variable_conflict use_variable
DECLARE admin_token text;cycle uuid;q int;q2 int;e uuid;e2 uuid;s1 uuid:=gen_random_uuid();s2 uuid:=gen_random_uuid();s3 uuid:=gen_random_uuid();s4 uuid:=gen_random_uuid();round_id uuid;other_round uuid;next_round uuid;p1 uuid;p2 uuid;p3 uuid;request uuid;result jsonb;before_time timestamptz;before_bank bigint;after_bank bigint;wave_count int;before_rows int;original_award jsonb;amount numeric;
BEGIN
 PERFORM pg_temp.check_it(current_database()='spark_mystery_monthly_release' AND inet_server_port()=55432,'isolated fixture');
 DELETE FROM spark_private.login_limits;admin_token:=public.spark_login(p_role=>'supervisor',p_pin=>'1618');
 INSERT INTO public.locations(id,location_code,school_name,active) VALUES(900003,'9903','Synthetic Third',true),(900004,'9904','Synthetic Fourth',true) ON CONFLICT(id) DO UPDATE SET active=true;
 INSERT INTO october_live.schools SELECT n,true FROM generate_series(900001,900004)n ON CONFLICT(location_id) DO UPDATE SET participating=true;
 UPDATE october_live.settings SET quests_state='active' WHERE id;
 INSERT INTO october_live.game_cycles(month,state) VALUES(date_trunc('month',now() AT TIME ZONE 'America/Los_Angeles')::date,'active') ON CONFLICT(month) DO UPDATE SET state='active',closed_at=NULL RETURNING id INTO cycle;
 SELECT coalesce(max(id),0)+100 INTO q FROM october_live.quests;q2:=q+1;
 INSERT INTO october_live.quests(id,name,description,enabled,reward_points,goal,cycle_id) VALUES(q,'Synthetic Showdown','Create a welcoming display.',true,10,'Celebrate your team.',cycle),(q2,'Independent Showdown','Arrange existing signs.',true,10,'Make it creative.',cycle);
 INSERT INTO october_live.entries(quest,location_id,photo_path,note,consent,state) VALUES(q,900001,gen_random_uuid()||'/'||gen_random_uuid()||'.webp','Original winner',true,'approved') RETURNING id INTO e;
 INSERT INTO october_live.quest_claims VALUES(q,e,900001);
 INSERT INTO october_live.rewards(event,location_id,points) VALUES('quest:first:'||q,900001,10);
 SELECT to_jsonb(r) INTO original_award FROM october_live.rewards r WHERE event='quest:first:'||q;
 INSERT INTO october_live.unlock_credit_events(location_id,kind,credits,price,service_date,quest_entry) VALUES(900001,'quest',3,0,current_date,e);
 SELECT coalesce(sum(credits),0) INTO before_bank FROM october_live.unlock_credit_events WHERE location_id=900001;
 SELECT count(*) INTO wave_count FROM october_live.game_wave_wins;
 SELECT public.spark_bingo_season_balance(900001) INTO amount;
 INSERT INTO public.spark_points(location_id,points,point_type,description,service_date,source,unique_key) VALUES(900001,(3-amount)::int,'test','Synthetic spending before challenge',current_date,'test','showdown-test-balance');
 BEGIN PERFORM public.october_games_live('showdown_submit','show-school-1',NULL,jsonb_build_object('quest',q,'request_id',gen_random_uuid(),'confirmed',true,'consent',true,'photo_path',gen_random_uuid()||'/'||gen_random_uuid()||'.webp'));RAISE EXCEPTION 'FAIL: self challenge';EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'Your school cannot%' THEN RAISE;END IF;END;
 result:=public.october_games_live('showdown_submit','show-school-2',NULL,jsonb_build_object('quest',q,'request_id',s1,'confirmed',true,'consent',true,'photo_path',gen_random_uuid()||'/'||gen_random_uuid()||'.webp'));
 PERFORM pg_temp.check_it((SELECT count(*) FROM october_live.showdown_rounds)=0,'pending does not start voting');
 BEGIN PERFORM public.october_games_live('showdown_approve','show-school-2',NULL,jsonb_build_object('id',s1,'revision',1));RAISE EXCEPTION 'FAIL: manager approval';EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'Supervisor%' THEN RAISE;END IF;END;
 result:=public.october_games_live('showdown_reject',NULL,admin_token,jsonb_build_object('id',s1,'revision',1,'feedback','PRIVATE TEST REASON'));
 result:=public.october_games_live('list','show-school-2',NULL,'{}');PERFORM pg_temp.check_it(position('PRIVATE TEST REASON' IN result::text)=0,'private feedback never public');
 PERFORM pg_temp.check_it(NOT EXISTS(SELECT 1 FROM october_live.showdown_used),'rejection preserves opportunity');
 result:=public.october_games_live('showdown_submit','show-school-2',NULL,jsonb_build_object('quest',q,'request_id',s2,'confirmed',true,'consent',true,'photo_path',gen_random_uuid()||'/'||gen_random_uuid()||'.webp'));
 result:=public.october_games_live('showdown_approve',NULL,admin_token,jsonb_build_object('id',s2,'revision',1));
 SELECT id,closes_at INTO round_id,before_time FROM october_live.showdown_rounds WHERE quest=q;
 SELECT id INTO p1 FROM october_live.showdown_photos WHERE showdown_photos.round_id=round_id AND location_id=900001;
 SELECT id INTO p2 FROM october_live.showdown_photos WHERE showdown_photos.round_id=round_id AND location_id=900002;
 PERFORM pg_temp.check_it((SELECT count(*)=2 FROM october_live.showdown_photos WHERE showdown_photos.round_id=round_id),'two approved photographs');
 PERFORM pg_temp.check_it(before_time>clock_timestamp()+interval '23 hours 59 minutes','24-hour deadline');
 BEGIN PERFORM public.october_games_live('showdown_vote','show-school-2',NULL,jsonb_build_object('round_id',round_id,'generation',1,'photo',p2));RAISE EXCEPTION 'FAIL: self vote';EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'Choose another%' THEN RAISE;END IF;END;
 result:=public.october_games_live('showdown_vote','show-school-4',NULL,jsonb_build_object('round_id',round_id,'generation',1,'photo',p2));
 result:=public.october_games_live('showdown_vote','show-school-4',NULL,jsonb_build_object('round_id',round_id,'generation',1,'photo',p1));
 result:=public.october_games_live('showdown_poll','show-school-4',NULL,'{}');
 PERFORM pg_temp.check_it((result->>'showdown_poll')::boolean AND position('photo_path' IN result::text)=0 AND position('private_feedback' IN result::text)=0,'live tally poll contains no private photo paths or review notes');
 PERFORM pg_temp.check_it((SELECT count(*)=1 FROM october_live.showdown_votes WHERE showdown_votes.round_id=round_id),'one mutable vote per school');
 result:=public.october_games_live('showdown_submit','show-school-3',NULL,jsonb_build_object('quest',q,'request_id',s3,'confirmed',true,'consent',true,'photo_path',gen_random_uuid()||'/'||gen_random_uuid()||'.webp'));
 PERFORM pg_temp.check_it((SELECT closes_at=before_time FROM october_live.showdown_rounds WHERE id=round_id),'pending does not reset timer');
 result:=public.october_games_live('showdown_approve',NULL,admin_token,jsonb_build_object('id',s3,'revision',1));
 PERFORM pg_temp.check_it((SELECT generation=2 AND closes_at>before_time FROM october_live.showdown_rounds WHERE id=round_id),'second approval restarts voting');
 PERFORM pg_temp.check_it((SELECT count(*)=0 FROM october_live.showdown_votes WHERE showdown_votes.round_id=round_id AND generation=2),'new generation starts empty');
 SELECT id INTO p3 FROM october_live.showdown_photos WHERE showdown_photos.round_id=round_id AND location_id=900003;
 INSERT INTO october_live.entries(quest,location_id,photo_path,note,consent,state) VALUES(q2,900003,gen_random_uuid()||'/'||gen_random_uuid()||'.webp','Independent winner',true,'approved') RETURNING id INTO e2;
 INSERT INTO october_live.quest_claims VALUES(q2,e2,900003);
 INSERT INTO october_live.rewards(event,location_id,points) VALUES('quest:first:'||q2,900003,10);
 result:=public.october_games_live('showdown_submit','show-school-4',NULL,jsonb_build_object('quest',q2,'request_id',s4,'confirmed',true,'consent',true,'photo_path',gen_random_uuid()||'/'||gen_random_uuid()||'.webp'));
 result:=public.october_games_live('showdown_approve',NULL,admin_token,jsonb_build_object('id',s4,'revision',1));
 SELECT id INTO other_round FROM october_live.showdown_rounds WHERE quest=q2;
 PERFORM pg_temp.check_it(other_round<>round_id AND (SELECT generation=2 FROM october_live.showdown_rounds WHERE id=round_id),'different quests have independent rounds');
 BEGIN PERFORM public.october_games_live('showdown_vote','show-school-1',NULL,jsonb_build_object('round_id',other_round,'generation',1,'photo',p2));RAISE EXCEPTION 'FAIL: vote crossed quests';EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'Choose another%' THEN RAISE;END IF;END;
 result:=public.october_games_live('showdown_vote','show-school-4',NULL,jsonb_build_object('round_id',round_id,'generation',2,'photo',p3));
 BEGIN PERFORM public.october_games_live('showdown_submit','show-school-4',NULL,jsonb_build_object('quest',q,'request_id',gen_random_uuid(),'confirmed',true,'consent',true,'photo_path',gen_random_uuid()||'/'||gen_random_uuid()||'.webp'));RAISE EXCEPTION 'FAIL: fourth photo';EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'Wait until%' THEN RAISE;END IF;END;
 BEGIN PERFORM public.october_games_live('showdown_finalize',NULL,admin_token,jsonb_build_object('round_id',round_id,'photo',p2,'revision',2,'confirmed',true,'request_id',gen_random_uuid()));RAISE EXCEPTION 'FAIL: early decision';EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'Wait for%' THEN RAISE;END IF;END;
 UPDATE october_live.showdown_rounds SET closes_at=clock_timestamp()-interval '1 second' WHERE id=round_id;
 result:=public.october_games_live('list',NULL,admin_token,'{}');
 BEGIN PERFORM public.october_games_live('showdown_vote','show-school-4',NULL,jsonb_build_object('round_id',round_id,'generation',2,'photo',p2));RAISE EXCEPTION 'FAIL: late vote';EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'Voting closed%' THEN RAISE;END IF;END;
 SELECT count(*) INTO before_rows FROM public.spark_points;
 request:=gen_random_uuid();
 result:=public.october_games_live('showdown_finalize',NULL,admin_token,jsonb_build_object('round_id',round_id,'photo',p2,'revision',(SELECT revision FROM october_live.showdown_rounds WHERE id=round_id),'confirmed',true,'request_id',request));
 PERFORM pg_temp.check_it(public.spark_bingo_season_balance(900001)=0,'previous champion stops at zero');
 PERFORM pg_temp.check_it((SELECT points_recovered=3 AND points_shortfall=7 FROM october_live.showdown_rounds WHERE id=round_id),'shortfall is explicit and auditable');
 PERFORM pg_temp.check_it((SELECT points=10 FROM october_live.rewards WHERE event='showdown:'||round_id||':award' AND location_id=900002),'challenger gets full reward independent of votes');
 PERFORM pg_temp.check_it((SELECT to_jsonb(r) FROM october_live.rewards r WHERE event='quest:first:'||q) IS NOT DISTINCT FROM original_award,'original reward unchanged');
 PERFORM pg_temp.check_it((SELECT entry=e AND location_id=900001 FROM october_live.quest_claims WHERE quest=q),'original winner record unchanged');
 PERFORM pg_temp.check_it((SELECT coalesce(sum(credits),0) FROM october_live.unlock_credit_events WHERE location_id=900001)=before_bank,'original unlock credits retained');
 PERFORM pg_temp.check_it((SELECT count(*)=1 FROM october_live.unlock_credit_events WHERE showdown_round=round_id AND location_id=900002 AND credits=3),'new winner receives three credits');
 PERFORM pg_temp.check_it((SELECT count(*) FROM october_live.game_wave_wins)=wave_count,'no regular weekly win added');
 result:=public.october_games_live('showdown_finalize',NULL,admin_token,jsonb_build_object('round_id',round_id,'photo',p2,'revision',1,'confirmed',true,'request_id',request));
 PERFORM pg_temp.check_it((SELECT count(*) FROM public.spark_points)=before_rows+2,'decision retry does not debit or credit twice');
 BEGIN PERFORM public.october_games_live('showdown_submit','show-school-1',NULL,jsonb_build_object('quest',q,'request_id',gen_random_uuid(),'confirmed',true,'consent',true,'photo_path',gen_random_uuid()||'/'||gen_random_uuid()||'.webp'));RAISE EXCEPTION 'FAIL: defeated defender rechallenge';EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'Your school has used%' THEN RAISE;END IF;END;
 s1:=gen_random_uuid();result:=public.october_games_live('showdown_submit','show-school-4',NULL,jsonb_build_object('quest',q,'request_id',s1,'confirmed',true,'consent',true,'photo_path',gen_random_uuid()||'/'||gen_random_uuid()||'.webp'));
 result:=public.october_games_live('showdown_approve',NULL,admin_token,jsonb_build_object('id',s1,'revision',1));
 SELECT id INTO next_round FROM october_live.showdown_rounds WHERE quest=q AND state='voting';
 PERFORM pg_temp.check_it(next_round<>round_id,'new independent round begins after finalization');
 UPDATE october_live.game_cycles SET state='archived',closed_at=clock_timestamp() WHERE id=cycle;
 BEGIN PERFORM public.october_games_live('showdown_submit','show-school-3',NULL,jsonb_build_object('quest',q,'request_id',gen_random_uuid(),'confirmed',true,'consent',true,'photo_path',gen_random_uuid()||'/'||gen_random_uuid()||'.webp'));RAISE EXCEPTION 'FAIL: closed competition accepted challenge';EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'This monthly%' THEN RAISE;END IF;END;
 UPDATE october_live.showdown_rounds SET closes_at=clock_timestamp()-interval '1 second' WHERE id=next_round;
 result:=public.october_games_live('list',NULL,admin_token,'{}');SELECT count(*) INTO before_rows FROM public.spark_points;
 SELECT id INTO p2 FROM october_live.showdown_photos WHERE showdown_photos.round_id=next_round AND role='defender';
 result:=public.october_games_live('showdown_finalize',NULL,admin_token,jsonb_build_object('round_id',next_round,'photo',p2,'revision',(SELECT revision FROM october_live.showdown_rounds WHERE id=next_round),'confirmed',true,'request_id',gen_random_uuid()));
 PERFORM pg_temp.check_it((SELECT count(*) FROM public.spark_points)=before_rows,'defender retention after month closing creates no financial change');
 PERFORM pg_temp.check_it(NOT has_table_privilege('anon','october_live.showdown_votes','SELECT') AND NOT has_function_privilege('authenticated','october_live.expire_showdowns()','EXECUTE'),'private tables and scheduler');
END$$;
SELECT 'PASS Showdown submission, rejection correction, authorization, three-photo limit, school votes, generation reset, deadlines, supervisor discretion, zero-floor reversal audit, idempotent credits, regular win preservation and post-month decisions';
